// Input: {distance_cm: 14.63}
var d = msg.payload.distance_cm;

// Piecewise linear volume
var volume;
if (d >= 16.30) {
    volume = 0;
} else if (d >= 15.98) {
    volume = (16.30 - d) / (16.30 - 15.98) * 100;
} else if (d >= 5.13) {
    volume = 100 + (15.98 - d) / (15.98 - 5.13) * 900;
} else {
    volume = 1000;
}

msg.payload = {
    distance_cm: d,
    volume_ml: Math.round(volume * 100) / 100
};

return msg;
